#!/bin/sh
# Fetch the images of docker-compose.yaml by digest into images/ (generated by hydo compose; hydo-build
# never pulls). Needs hydo-fetch-image (it comes with hydo) and network access, once.
# It fetches the images this machine builds: x86_64 on Linux, arm64 on a Mac. Name
# x86_64, arm64 or all as the argument to choose (sh fetch-images.sh all).
set -eu
cd "$(dirname "$0")"
A=${1:-}
[ -n "$A" ] || case "$(uname -s)" in Darwin) A=arm64;; *) A=x86_64;; esac
case "$A" in x86_64|arm64|all) ;; *) echo "fetch-images.sh: x86_64, arm64 or all (got $A)" >&2; exit 2;; esac
F=${HYDO_FETCH_IMAGE:-$(command -v hydo-fetch-image || true)}
[ -n "$F" ] || { echo "fetch-images.sh: hydo-fetch-image not found (put hydo's bin directory on PATH, or set HYDO_FETCH_IMAGE)" >&2; exit 1; }
mkdir -p images
[ "$A" = x86_64 ] || [ -e images/apachepulsar-pulsar-5.0.1-arm64-oci ] || "$F" docker.io/apachepulsar/pulsar sha256:5e5a13f0f5c5bd82466a41a12f299b925c1771f5f58781eca61a9d2a20c7b3ef apachepulsar/pulsar:5.0.1 images/apachepulsar-pulsar-5.0.1-arm64-oci
[ "$A" = arm64 ] || [ -f images/apachepulsar-pulsar-5.0.1-amd64.docker.tar ] || "$F" docker.io/apachepulsar/pulsar sha256:fb95bc2d73687ef7df3a21f3424a897860926e25303bd3857898ab887ead85c3 apachepulsar/pulsar:5.0.1 images/apachepulsar-pulsar-5.0.1-amd64.docker.tar
[ "$A" = arm64 ] || ls -ld images/apachepulsar-pulsar-5.0.1-amd64.docker.tar
[ "$A" = x86_64 ] || ls -ld images/apachepulsar-pulsar-5.0.1-arm64-oci
